#!/usr/bin/env python3
"""PRED-C1-r50 companion — the live hyprctl bind receipt, regenerated byte-identically.

The receipt answers the counter's live-capture clause (round 49 `clause f`, replayed by
`clause r`): `hyprctl binds -j` is named, the raw JSON is digested but never embedded, the bind
total and the four key-form counts are stated once and summed, `input:resolve_binds_by_sym`
is stated, and the version line carries `Hyprland 0.56.2` plus commit `efb50993…`. Shape only:
no bind arg, description, dispatcher text, device name, window title or home path is written.

Usage:
    python3 make-receipt.py --out binds-live-r50.txt [--shape-out binds-shape-r50.txt]
                            [--work DIR] [--compare PATH] [--verify COUNTER.py]

  --out        the live receipt (required).
  --shape-out  optional per-field shape receipt, same capture.
  --work       sandbox root for HOME/XDG_*; defaults to TMPDIR. A work dir under /tmp,
               /var/tmp, /dev/shm or the account home is refused, and an absent one is refused
               too — a SIGKILL must never leave the sandbox inside real home state.
  --compare    a previous live receipt of this shape; emits `vs_prior` lines (digest, total,
               forms, histogram). Used to say what moved since round 49.
  --verify     import that counter module and re-parse the emitted live receipt with its own
               helpers (forms_in/total_in/digest_in/resolve_in/version_ok) — the counter's
               readability, checked at emit time instead of by a reader.

Determinism: every value below is measured or derived; the only clock input is the capture date
(YYYY-MM-DD, UTC). Two runs on one boot with one bind table produce identical bytes; the bind
digest line changes exactly when the bind table changes.
"""
import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from collections import Counter
from datetime import datetime, timezone

FORMS = ("named", "code", "mouse", "switch")
RESOLVE_OPTION = "input:resolve_binds_by_sym"
REFUSE = ("/tmp", "/var/tmp", "/dev/shm", "/home", "/root", "/Users")
KEEP_ENV = ("XDG_RUNTIME_DIR", "HYPRLAND_INSTANCE_SIGNATURE")
CAPTURES = 3


class Fail(Exception):
    pass


def home_roots():
    """The account's home as $HOME and as the passwd entry both name it (neither is trusted alone)."""
    roots = set()
    h = os.environ.get("HOME")
    if h:
        roots.add(os.path.realpath(h))
    try:
        import pwd
        roots.add(os.path.realpath(pwd.getpwuid(os.getuid()).pw_dir))
    except (ImportError, KeyError):
        pass
    return {r for r in roots if r and r != "/"}


def work_root(arg):
    """A populated sandbox root outside /tmp, /var/tmp, /dev/shm and the account home."""
    raw = arg or os.environ.get("TMPDIR")
    if not raw:
        raise Fail("work dir required: pass --work or set TMPDIR")
    rp = os.path.realpath(raw)
    for bad in REFUSE:
        if rp == bad or rp.startswith(bad + "/"):
            raise Fail("work dir under %s refused: %s" % (bad, rp))
    for home in home_roots():
        if rp == home or rp.startswith(home + "/"):
            # a SIGKILL would leave the sandbox behind in real home state, which no seat may write
            raise Fail("work dir under the account home refused: %s" % rp)
    try:
        os.makedirs(rp, exist_ok=True)
    except OSError as e:
        raise Fail("work dir not creatable: %s (%s)" % (rp, e.strerror or e))
    if not os.path.isdir(rp):
        raise Fail("work dir is not a directory: %s" % rp)
    return rp


def clean_env(sandbox):
    """hyprctl sees only its socket path; every writable home variable lands in the sandbox."""
    env = {"PATH": "/usr/bin", "LANG": "C.UTF-8"}
    for keep in KEEP_ENV:
        if not os.environ.get(keep):
            raise Fail("%s required for a live capture" % keep)
        env[keep] = os.environ[keep]
    for key in ("HOME", "XDG_CONFIG_HOME", "XDG_CACHE_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME"):
        env[key] = os.path.join(sandbox, key.lower())
        os.makedirs(env[key], exist_ok=True)
    return env


def run(argv, env, stdin_devnull=True):
    p = subprocess.run(argv, capture_output=True, env=env, timeout=60,
                       stdin=subprocess.DEVNULL if stdin_devnull else None)
    return p.returncode, p.stdout, p.stderr


def capture(hyprctl, env):
    """(raw binds bytes, version stdout, getoption stdout) — the three read-only reads."""
    digests = []
    raw = None
    for _ in range(CAPTURES):
        rc, out, err = run([hyprctl, "binds", "-j"], env)
        if rc != 0:
            raise Fail("hyprctl binds -j rc=%d: %s" % (rc, err.decode("utf-8", "replace").strip()))
        digests.append(hashlib.sha256(out).hexdigest())
        if raw is None:
            raw = out
    if len(set(digests)) != 1:
        raise Fail("bind table moved between captures: %s" % sorted(set(digests)))
    rc, ver, err = run([hyprctl, "version"], env)
    if rc != 0:
        raise Fail("hyprctl version rc=%d" % rc)
    rc, opt, err = run([hyprctl, "getoption", RESOLVE_OPTION, "-j"], env)
    if rc != 0:
        raise Fail("hyprctl getoption rc=%d" % rc)
    return raw, ver.decode("utf-8", "replace"), opt.decode("utf-8", "replace")


def version_line(ver):
    for line in ver.splitlines():
        if re.search(r"Hyprland\s+0\.56\.2", line) and re.search(r"\b[0-9a-f]{40}\b", line):
            return line.strip()
    raise Fail("hyprctl version carries no Hyprland 0.56.2 + commit line")


def resolve_int(opt):
    for line in opt.splitlines():
        m = re.search(r'"int"\s*:\s*(-?\d+)', line)
        if m:
            return int(m.group(1)), bool(re.search(r'"set"\s*:\s*true', line))
    raise Fail("getoption reply carries no int")


def form_counts(binds):
    """The counter's rule: code:/mouse/switch: prefix -> that form; empty key + keycode -> code."""
    forms = dict.fromkeys(FORMS, 0)
    keycodes = set()
    for b in binds:
        key = b.get("key") or ""
        kc = b.get("keycode") or 0
        if isinstance(key, str) and key.startswith("code:"):
            forms["code"] += 1
        elif isinstance(key, str) and key.startswith("mouse"):
            forms["mouse"] += 1
        elif isinstance(key, str) and key.startswith("switch:"):
            forms["switch"] += 1
        elif key == "" and kc:
            # `hyprctl binds -j` prints a keycode bind with an empty key field, so the keycode is
            # the only trace of a `code:` bind in the dump (the `code:` prefix is the bind-line form)
            forms["code"] += 1
            keycodes.add(int(kc))
        else:
            forms["named"] += 1
    return forms, keycodes


def histogram(binds):
    return sorted(Counter(int(b.get("modmask") or 0) for b in binds).items())


def live_text(raw, ver, opt, binds, date, seat):
    forms, keycodes = form_counts(binds)
    total = len(binds)
    sha = hashlib.sha256(raw).hexdigest()
    rv, rset = resolve_int(opt)
    if any(forms[k] == 0 for k in FORMS):
        raise Fail("a key form is empty, so the form rule read the dump wrong: %s" % forms)
    if sum(forms.values()) != total:
        raise Fail("form counts do not sum to the bind total: %s != %d" % (forms, total))
    hist = histogram(binds)
    if sum(n for _, n in hist) != total:
        raise Fail("modmask histogram does not sum to the bind total")
    kc_span = ",".join(str(k) for k in sorted(keycodes))
    L = [
        "# mado round 50 w1 - read-only live host receipt: hyprctl bind surface (counts and shape only)",
        "# generator: .ufo/waves/round-50/w1/%s/make-receipt.py (same capture -> same bytes)" % seat,
        "# clean env: HOME/XDG_* under the sandbox, only XDG_RUNTIME_DIR and the instance signature kept",
        "command: hyprctl version",
        "hyprctl version: " + version_line(ver),
        "command: hyprctl binds -j",
        "sha256: %s   (raw JSON bytes, %d; not embedded in this file)" % (sha, len(raw)),
        "key_form_rule: key starting code:/mouse/switch: -> that form; "
        "key == \"\" AND keycode != 0 -> code; otherwise named",
        "binds=%d named=%d code=%d mouse=%d switch=%d catch_all=%d" % (
            total, forms["named"], forms["code"], forms["mouse"], forms["switch"],
            sum(1 for b in binds if b.get("catch_all"))),
        "modmask_histogram (modmask count):",
    ]
    L += ["  %d %d" % (mask, n) for mask, n in hist]
    L += [
        "command: hyprctl getoption %s -j" % RESOLVE_OPTION,
        "%s int=%d set=%s" % (RESOLVE_OPTION, rv, "true" if rset else "false"),
        "",
        "reads used: hyprctl version, hyprctl binds -j, hyprctl getoption %s -j (read-only;"
        % RESOLVE_OPTION,
        "no dispatcher, keyword, reload or batch call was made).",
        "stability: %d consecutive captures in this generator run produced the same digest and counts."
        % CAPTURES,
        "the key field never carries a code: prefix: every keycode bind carries an empty key field plus a",
        "non-zero keycode, over %d distinct keycodes %s (xkb numbering, evdev + 8)." % (
            len(keycodes), kc_span),
        "the histogram partitions the same bind table: masks with count 0 are absent from this list.",
        "no device name, window title, dispatcher argument, bind description or home path appears in this file.",
        "captured %s (UTC) by seat %s, round 50 w1; this file states counts and shape only."
        % (date, seat),
    ]
    return "\n".join(L) + "\n"


def shape_text(binds, raw, date, seat):
    forms, keycodes = form_counts(binds)
    total = len(binds)
    names = " ".join(sorted(binds[0].keys())) if binds else ""
    key_named = forms["named"]
    upper = sum(1 for b in binds
                if len(b.get("key") or "") == 1 and (b.get("key") or "").isupper())
    hist = histogram(binds)
    L = [
        "# mado round 50 w1 - read-only host receipt: hyprctl bind surface, per-field shape",
        "# commands: hyprctl version ; hyprctl binds -j ; hyprctl getoption %s -j" % RESOLVE_OPTION,
        "# captured %s, clean env (HOME/XDG_* under the sandbox), no dispatcher called" % date,
        "# same capture as this generator's live receipt (its sha256 line names this digest):"
        " sha256 %s, %d bytes"
        % (hashlib.sha256(raw).hexdigest(), len(raw)),
        "",
        "binds_total: %d" % total,
        "field_names: " + names,
        "field_count: %d" % (len(names.split())),
        "keycode_nonzero: %d" % sum(1 for b in binds if (b.get("keycode") or 0)),
        "distinct_keycodes: %d" % len(keycodes),
        "keycode_values: " + ",".join(str(k) for k in sorted(keycodes)),
        "key_empty: %d" % sum(1 for b in binds if (b.get("key") or "") == ""),
        "mouse_flag_true: %d" % sum(1 for b in binds if b.get("mouse") is True),
        "key_mouse_prefix: %d" % forms["mouse"],
        "key_switch_prefix: %d" % forms["switch"],
        "key_named_total: %d" % key_named,
        "key_single_upper_letter: %d" % upper,
        "key_named_other: %d" % (key_named - upper),
        "catch_all_true: %d" % sum(1 for b in binds if b.get("catch_all")),
        "submap_empty: %d" % sum(1 for b in binds if not (b.get("submap") or "")),
        "ignore_mods_present: %d (the dump has no such field, so an ignore-mods count is not a measurement)"
        % sum(1 for b in binds if "ignore_mods" in b),
        "modmask_histogram (modmask count):",
    ]
    L += ["  %d %d" % (mask, n) for mask, n in hist]
    return "\n".join(L) + "\n"


def parse_prior(text):
    """The values a prior live receipt of this shape states (sha, total, forms, histogram)."""
    sha = re.search(r"^sha256:\s*([0-9a-f]{64})", text, re.M)
    tot = re.search(r"^binds=(\d+)\s+named=(\d+)\s+code=(\d+)\s+mouse=(\d+)\s+switch=(\d+)",
                    text, re.M)
    if not sha or not tot:
        raise Fail("--compare file is not a live receipt of this shape")
    hist = []
    for line in text.splitlines():
        m = re.fullmatch(r"\s+(\d+) (\d+)", line)
        if m:
            hist.append((int(m.group(1)), int(m.group(2))))
    return {"sha": sha.group(1), "total": int(tot.group(1)),
            "forms": dict(zip(FORMS, (int(tot.group(k)) for k in range(2, 6)))),
            "hist": sorted(hist)}


def compare_lines(prior, raw, binds):
    forms, _ = form_counts(binds)
    sha = hashlib.sha256(raw).hexdigest()
    out = ["vs_prior: sha256_equal=%s total=%d/%d" % (sha == prior["sha"], len(binds),
                                                      prior["total"])]
    for k in FORMS:
        out.append("vs_prior: %s=%d/%d" % (k, forms[k], prior["forms"][k]))
    if not prior["hist"]:
        out.append("vs_prior: histogram_in_prior=no (sha and counts compared; the prior receipt "
                   "states no histogram)")
        return "\n".join(out) + "\n"
    now, before = dict(histogram(binds)), dict(prior["hist"])
    moved = [m for m in sorted(set(now) | set(before)) if now.get(m) != before.get(m)]
    out.append("vs_prior: modmask_moved=%s" % (",".join(str(m) for m in moved) if moved else "none"))
    return "\n".join(out) + "\n"


def verify_counter(path, live):
    """Re-read the emitted receipt with the counter's helpers (its own readability rule)."""
    import importlib.util
    spec = importlib.util.spec_from_file_location("counter_mod", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    need = ("forms_in", "total_in", "digest_in", "resolve_in", "version_ok")
    missing = [n for n in need if not hasattr(mod, n)]
    if missing:
        raise Fail("counter module lacks helpers: %s" % missing)
    forms = mod.forms_in(live)
    totals = mod.total_in(live)
    digests = mod.digest_in(live)
    if mod.resolve_in(live) != {0}:
        raise Fail("counter reads resolve as %s" % sorted(mod.resolve_in(live)))
    if not mod.version_ok(live):
        raise Fail("counter reads no version line")
    if len(digests) != 1 or len(totals) != 1:
        raise Fail("counter reads digests=%d totals=%d" % (len(digests), len(totals)))
    stated = {k: (sorted(v) if isinstance(v, set) else v) for k, v in forms.items()}
    if any(len(v) != 1 for v in stated.values()):
        raise Fail("counter reads forms %s" % stated)
    if sum(next(iter(v)) for v in stated.values()) != totals.pop():
        raise Fail("counter's form sum disagrees with its total")
    return "COUNTER_HELPERS: ok forms=%s sha=%s" % (
        ",".join("%s:%d" % (k, next(iter(stated[k]))) for k in stated), digests.pop()[:12])


def main():
    ap = argparse.ArgumentParser(description="regenerate the round-50 live hyprctl bind receipt")
    ap.add_argument("--out", required=True)
    ap.add_argument("--shape-out")
    ap.add_argument("--work")
    ap.add_argument("--compare")
    ap.add_argument("--verify")
    ap.add_argument("--hyprctl", default="/usr/bin/hyprctl")
    ap.add_argument("--date", default=None, help="capture date, YYYY-MM-DD (default: UTC today)")
    ap.add_argument("--seat", default="ExecLiveR50")
    a = ap.parse_args()

    if not os.path.isfile(a.hyprctl):
        raise Fail("hyprctl missing: %s" % a.hyprctl)
    date = a.date or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
        raise Fail("--date must be YYYY-MM-DD")
    root = work_root(a.work)
    try:
        sandbox = tempfile.mkdtemp(dir=root, prefix="binds-")
    except OSError as e:
        raise Fail("sandbox not creatable under %s (%s)" % (root, e.strerror or e))
    try:
        env = clean_env(sandbox)
        raw, ver, opt = capture(a.hyprctl, env)
        binds = json.loads(raw.decode("utf-8"))
        if not isinstance(binds, list):
            raise Fail("hyprctl binds -j is not a JSON array")
        live = live_text(raw, ver, opt, binds, date, a.seat)
        # --compare and --verify report on stdout only: the receipt stays the canonical bytes that
        # a plain run reproduces, whatever extra checks the caller asked for
        notes = []
        if a.compare:
            with open(a.compare, encoding="utf-8", errors="replace") as f:
                notes.append(compare_lines(parse_prior(f.read()), raw, binds))
        if a.verify:
            notes.append(verify_counter(a.verify, live) + "\n")
        with open(a.out, "w", encoding="utf-8", newline="\n") as f:
            f.write(live)
        if a.shape_out:
            with open(a.shape_out, "w", encoding="utf-8", newline="\n") as f:
                f.write(shape_text(binds, raw, date, a.seat))
        forms, _ = form_counts(binds)
        for note in notes:
            sys.stdout.write(note)
        print("MADO_BINDS_RECEIPT: sha=%s binds=%d forms=%s out=%s"
              % (hashlib.sha256(raw).hexdigest()[:12], len(binds),
                 ",".join("%s:%d" % (k, forms[k]) for k in FORMS), a.out))
    finally:
        shutil.rmtree(sandbox, ignore_errors=True)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Fail as e:
        print("MADO_BINDS_RECEIPT: FAILED %s" % e, file=sys.stderr)
        sys.exit(2)
